-- Rolled-back test for 0039 (write, test in a rolled-back transaction, dry-run, push). Job B.2: hues, reference pictures.
--
--   node scripts/build-sql-test.mjs 0039 && supabase db query --linked -f scripts/test-0039.sql

-- Generated by scripts/build-sql-test.mjs from test-0039.head.sql, 0039, test-0039.body.sql.
begin;
-- Job B.2 (Home v4, Figma 1737:2): flat project hues, and a reference picture for every idea that has no picture of its own.
--
--   projects.hue             coral | sage | butter | slate, assigned as projects are made, cycling in that order; My
--                            things is always cool-grey. The hue is a card's fallback block while a picture is found,
--                            the chip's underline, and the project's swatch. Ink text on every hue. Replaces the
--                            gradients (0034) everywhere they were drawn; projects.gradient and its trigger stay, unread.
--   cards.reference_picture  The first free reference for the card (findReferences(card, {limit: 1})), stored so Home
--                            doesn't search on every open: {source, id, url, thumb_url, link_url, credit: {name, url},
--                            width, height, track_url?}. Unsplash or Pixabay only, never Pinterest (its terms: pins are
--                            never stored). Shown only when the card has no picture of its own and no Unsplash photo.
--                            The image itself is never copied: url is the provider's (Unsplash hotlinking rules).

-- ── Hues ────────────────────────────────────────────────────────────────────────────────────────────────────────

create function project_hues() returns text[]
language sql
immutable
as $$
  select array['coral', 'sage', 'butter', 'slate'];
$$;

alter table projects add column hue text check (hue = any (project_hues()) or hue = 'cool-grey');

-- My things is cool-grey. Anything else takes the next hue for its creator: how many of her projects already wear
-- one of the four, round the four. A multi-row insert sees the rows before it in the same statement (as 0034's does).
create function assign_project_hue() returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.kind = 'things' then
    new.hue := 'cool-grey';
  elsif new.hue is null then
    new.hue := (project_hues())[
      (select count(*) from projects where creator_id = new.creator_id and kind <> 'things') % array_length(project_hues(), 1) + 1
    ];
  end if;
  return new;
end;
$$;
revoke execute on function assign_project_hue() from public, anon, authenticated;

create trigger projects_assign_hue before insert on projects
  for each row execute function assign_project_hue();

-- Backfill: My things cool-grey; each creator's other projects in the order she made them.
update projects set hue = 'cool-grey' where kind = 'things';
update projects p
   set hue = (project_hues())[((o.n - 1) % array_length(project_hues(), 1)) + 1]
  from (
    select id, row_number() over (partition by creator_id order by created_at, is_default desc, id) as n
      from projects
     where kind <> 'things'
  ) o
 where o.id = p.id;

alter table projects alter column hue set not null;

-- ── Reference pictures ──────────────────────────────────────────────────────────────────────────────────────────

alter table cards add column reference_picture jsonb
  check (reference_picture is null or (reference_picture ->> 'source') in ('unsplash', 'pixabay'));

create temp table r(n serial, check_name text, ok boolean, detail text) on commit drop;

do $$
declare
  me text := 'user_3JfYR4D8eJVCL3yieXStYYoqwaH';
  bad int; hue_seq text; p1 uuid; p2 uuid; things_hue text; c uuid;
begin
  select count(*) into bad from projects where hue is null;
  insert into r values (default, 'every project has a hue', bad = 0, bad::text);
  select count(*) into bad from projects where kind = 'things' and hue <> 'cool-grey';
  insert into r values (default, 'My things is cool-grey', bad = 0, bad::text);
  select count(*) into bad from projects where kind <> 'things' and hue = 'cool-grey';
  insert into r values (default, 'only My things is cool-grey', bad = 0, bad::text);
  select string_agg(hue, ',' order by created_at, is_default desc, id) into hue_seq from projects where creator_id = me and kind <> 'things';
  insert into r values (default, 'backfill cycles coral, sage, butter, slate in creation order', hue_seq like 'coral,sage%', hue_seq);

  insert into projects (creator_id, name) values (me, 'Hue test A') returning id into p1;
  insert into projects (creator_id, name) values (me, 'Hue test B') returning id into p2;
  select string_agg(hue, ',' order by created_at, id) into hue_seq from projects where id in (p1, p2);
  insert into r values (default, 'new projects take the next hues', hue_seq is not null and hue_seq not like '%cool-grey%', hue_seq);
  insert into r values (default, 'consecutive projects differ', (select count(distinct hue) from projects where id in (p1, p2)) = 2, hue_seq);

  select id into c from cards where creator_id = me limit 1;
  update cards set reference_picture = '{"source": "pixabay", "id": "1", "url": "https://x", "thumb_url": "https://x", "link_url": "https://x", "credit": {"name": "a", "url": "https://x"}, "width": 1, "height": 1}' where id = c;
  insert into r values (default, 'a Pixabay reference picture is accepted', true, c::text);
  begin
    update cards set reference_picture = '{"source": "pinterest", "id": "1"}' where id = c;
    insert into r values (default, 'a Pinterest reference picture is refused', false, 'updated');
  exception when check_violation then
    insert into r values (default, 'a Pinterest reference picture is refused', true, sqlerrm);
  end;
end $$;

select n, case when ok then 'pass' else 'FAIL' end as result, check_name, detail from r order by n;
rollback;
